  "about_items": [
    {
      "n": "#83·35",
      "text": "This beige wool dress features a relaxed, cable-knit texture and soft pockets at the hips for subtle detail. Its gentle drape falls to mid-thigh, creating a comfortable yet polished silhouette perfect for an autumn date."
    },
    {
      "n": "#207·20",
      "text": "The light blue cardigan is crafted from airy mesh knit fabric that feels delicate and light. It has a loose V-neckline with three decorative buttons running down the front, adding just enough structure without weighing down the look."
    },
    {
      "n": "#15·22",
      "text": "These grey suede pump heels have a classic pointed toe and slender heel that elongate your legs while maintaining effortless charm. The soft suede finish matches well with both the knitwear and woven textures in your outfit."
    },
    {
      "n": "#356·07",
      "text": "This woven clutch bag features a structured rectangular shape with geometric patterns on the front flap. It has a sleek black leather handle and an elegant gold-tone metal clasp closure that adds a touch of refinement."
    }
  ]
}
